  const trimmed = text.trim();
  if (trimmed.startsWith('-')) return -toHundredths(trimmed.slice(1));
  const [whole, frac = ''] = trimmed.split('.');
  return BigInt(whole || '0') * 100n + BigInt((frac + '00').slice(0, 2));
